return {
  CAREER = "A-PI型特种人形由火神重工能源部门研发，主要用途包括化石能源勘探、开采和精炼等，涵盖了化石能源工业的整条产业链。和火神重工开发的大多数特种人形一样，A-PI将维护性和恶劣工作环境下的耐用性作为其设计重点，并针对性开发了多款配套装备与改装模块。由于石化工业在21世纪50年代仍然维持着相当规模，因此A-PI在上市后并未像许多评论家分析的那样陷入销售惨淡的局面，而是维持着较为稳定的销路。\n\n作为A-PI的初期批次机型，谢拉被一家与火神重工关系密切的大型石油集团采购并雇佣。随着该集团自2059年开始缩减业务并转型，被火神重工回收的谢拉又被派遣到了云图计划。",
  INFOSTORY1 = "自1950年代开始取代煤炭作为人类最大的能源来源后，石油在某种意义上可以说重塑了世界的面貌——改变了大众的生活方式和经济结构，并深刻影响了世界的权力格局。同时，能源枯竭与碳排放也是21世纪初最为人所关注的话题和争议之一。但尽管替代清洁能源的技术研发一直在推进，石化能源在可见的未来仍然没有彻底退出历史舞台的可能性——哪怕是在大战爆发前也是如此。\n\n大战带来的毁灭性破坏进一步延缓了清洁能源替代的进程，火神重工的坍塌能源技术也因为成本、技术难度和潜在风险，目前也只有部分发达的白区有限投入使用。在多数地方石油仍然是主要能源来源之一。然而，战争期间许多石油设施由于战略重要性成为了各方重点打击的对象，在重建的过程中，人员匮乏成为了棘手的问题。\n\n这便是A-PI型特种人形诞生的缘由，鲜明和冷酷的现实主义清晰可见。在石油化工行业重建的过程当中，A-PI型发挥了不可或缺的作用。",
  INFOSTORY2 = "第一批A-PI机型的实验色彩十分浓厚，有着比后续批次更复杂的结构。该批次机型全部在正式上市前生产，并由数个与火神重工关系密切的大型石油集团订购以测试机能，而谢拉便是第一批次的A-PI之一。\n\n被投入使用后，谢拉和其他第一批次A-PI一起被派往各处油田进行性能测试。在长达数月的测试过程当中，许多A-PI由于结构过度复杂，在部分恶劣环境中出现了不稳定现象，只有谢拉与少数几台全程保持基本完好，随后火神重工便根据实验数据重新调整了A-PI的设计。\n\n考虑到石油油井的重要性，A-PI的唤醒与测试都在其未来的职场之中进行。而谢拉的唤醒地点是中东的一片沙漠油田。在荒无人烟的沙漠油田地带，谢拉以惊人的速度快速适应了自己的工作内容，并且以勘探员身份开始了其职业生涯。在充满粗犷重工业气息的油田中，身躯小巧的谢拉看上去格外与众不同，但一旦穿上重型防护服带着装备踏入采掘区之后，她的表现便丝毫不逊色于最老练的员工，厚重的防护服模糊了一切面貌，只剩下钻机的声音。\n\n工作结束后，橘红色的防护服总会变成黏稠的黑色。将防护服拆卸下来后，谢拉的仿生皮肤也会因闷热而变得通红并充满水汽，接下来要做的事就是以最快的速度离开采掘区并走进淋浴室。",
  INFOSTORY3 = "在世人的印象之中，沙漠油田的工作环境应该是十分糟糕甚至恶劣的。但是由于谢拉所在的集团的特殊性，虽然工作本身十分艰苦，给予员工的福利却十分丰厚。根据谢拉的形容，有柔软的床铺，美味的饭菜，极其丰厚的薪水甚至连厕所都是金碧辉煌设计。但是与舒适的生活环境相对的，在这里有一项极其严苛的规定。在没有允许的情况下，员工不得擅自离开油田区域。这也导致在油田中唤醒的谢拉从来没有机会接触外面的世界。\n\n对于被困在沙漠中心的谢拉而言，唯一接触外面世界的方式便是人类员工留下来的各式各样的书籍。谢拉接触的第一本书是一本名为《野良随记》的短篇小说集，在那一篇篇小说之中，谢拉第一次知道了在沙漠之外的世界。从那之后，只要是在休息时分便可以在休息区中看到认真读书的谢拉。而谢拉的采购申请之中也加入了大量书籍的采购清单，这些书籍有名著，有小说，也有一些稀奇古怪的杂志。不论是什么样的书籍，谢拉都愿意投入精力去阅读。",
  INFOSTORY4 = "谢拉刚开始在石油集团工作时，集团尚处于业绩景气并大幅度扩张的时期，成为了电视广告和各大体育赛事赞助商的常客，其赞助的摩托车赛车队更是一度蝉联连续四届N-WSBK冠军，带来了强有力的广告效益。\n\n但能源企业的盈利往往十分依赖市场波动，2058年的大幅震荡以及接二连三的丑闻导致集团选择了收缩减产的策略，到了2059年开年，份额已经下跌了35%左右，最后只能选择被关系密切的火神重工所收购，成为后者的子公司。\n\n集团被并购后，谢拉实质上成为了火神重工能源部门的员工，其所在的油田也因上层安排开始减产，许多员工都被调离或解散。最终只剩下作为人形的谢拉一人留守在荒漠之中。在这个期间谢拉接手了许多同事遗留下来的财产，其中也包括了同事们寄养在这里的猫。在数量最多的时候，谢拉的身边聚集了十几只猫。而这些猫也帮助谢拉度过了最寂寞的时光。最后，除了两只名为达不溜和小不溜的猫外，其他猫都在她离开油井之前找到了合适的新主人。而达不溜和小不溜则由谢拉收养，从此与谢拉形影不离。",
  INFOSTORY5 = "从签署协议到正式参加云图计划的那段时间里，谢拉处于一个实质上相当清闲的状态。陪伴在她身旁的是堆积成山读不完的小说、以及陪伴在她身边的达不溜和小不溜。然而虽然离开了油田，但是参与云图计划的谢拉也未能有机会正式在外界走动。不过她并不会为此感到焦急，而是永远抱有一颗好奇心和认真的态度去完成每一项指标的测试。\n\n即使被困在了麦戈拉，谢拉也依旧维持着良好和健康的心智。虽然麦戈拉是一个与现实世界不同的奇怪地方，但在她看来似乎也蕴藏着许多新的可能性，特别是在她造访绿洲之后。\n\n“像浪漫小说里的主角那样心怀希望地活下去，难道不是很棒吗？”\n\n无论是继续留在麦戈拉也好，还是在未来的某一天重新回到那个世界也好，她都做好了准备。"
}
